async def act(page):
    # Step 1: Check current page for 'Archives' in main content
    content = await extract_main_content(page, '/')
    if 'Archives' in content:
        # Find the 'Archives' section using get_by_text
        archives_section = page.get_by_text('Archives', exact=False)
        if await archives_section.count() > 0:
            # Get the parent element that contains 'Archives' to find links
            # Use get_by_role to find a containing element like 'section' or 'group'
            possible_roles = ['region', 'complementary', 'navigation', 'group', 'section']
            parent = None
            for role in possible_roles:
                elements = page.get_by_role(role)
                count = await elements.count()
                for i in range(count):
                    element = elements.nth(i)
                    # Check if this element contains the 'Archives' text
                    if await element.get_by_text('Archives', exact=False).count() > 0:
                        parent = element
                        break
                if parent:
                    break
            if parent:
                links = parent.get_by_role('link')
                link_count = await links.count()
                if link_count >= 2:
                    await links.nth(1).click()
                    await page.wait_for_load_state('networkidle')
                    return
                else:
                    print(f'Found Archives section but only {link_count} links.')
                    return
            else:
                print('Could not find parent role for Archives section.')
                return
        else:
            print('Archives text not found on current page.')
            return
    else:
        # 'Archives' not on homepage, navigate to 'Sample Page'
        sample_page_link = page.get_by_role('link', name='Sample Page', exact=True)
        if await sample_page_link.count() > 0:
            await sample_page_link.click()
            await page.wait_for_load_state('networkidle')
            # Check for 'Archives' on the new page
            content = await extract_main_content(page, '/?page_id=2')
            if 'Archives' in content:
                archives_section = page.get_by_text('Archives', exact=False)
                if await archives_section.count() > 0:
                    # Find parent as above
                    possible_roles = ['region', 'complementary', 'navigation', 'group', 'section']
                    parent = None
                    for role in possible_roles:
                        elements = page.get_by_role(role)
                        count = await elements.count()
                        for i in range(count):
                            element = elements.nth(i)
                            if await element.get_by_text('Archives', exact=False).count() > 0:
                                parent = element
                                break
                        if parent:
                            break
                    if parent:
                        links = parent.get_by_role('link')
                        link_count = await links.count()
                        if link_count >= 2:
                            await links.nth(1).click()
                            await page.wait_for_load_state('networkidle')
                            return
                        else:
                            print(f'On Sample Page: Found Archives section but only {link_count} links.')
                            return
                    else:
                        print('On Sample Page: Could not find parent role for Archives section.')
                        return
                else:
                    print('On Sample Page: Archives text not found.')
